/**
 * Emit the identification-eval table into the README and the post.
 *
 * The numbers in those documents are not typed by hand. They are generated from
 * docs/evidence/identify-results.json, which is itself generated by
 * apps/brain/eval/run-identify.ts from a hand-labelled set. Run this after the eval:
 *
 *   pnpm evidence:tables
 *
 * It rewrites only what sits between the markers, so the surrounding prose is safe.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

interface Row {
  itemId: string;
  parseOk: boolean;
  brandOk: boolean;
  typeOk: boolean;
  inventedBrand: boolean;
  ms: number;
}

interface Variant {
  id: string;
  label: string;
  schema: boolean;
  rows: Row[];
}

interface Results {
  model: string;
  temperature: number;
  items: number;
  itemsWithBrand: number;
  itemsWithoutBrand: number;
  variants: Variant[];
}

const ROOT = resolve(import.meta.dirname, "..");
const EVIDENCE = resolve(ROOT, "docs/evidence/identify-results.json");

const pct = (n: number, d: number) => (d === 0 ? "—" : `${Math.round((n / d) * 100)}%`);

function median(rows: Row[]) {
  const xs = rows.map((r) => r.ms).sort((a, b) => a - b);
  return xs[Math.floor(xs.length / 2)] ?? 0;
}

function build(data: Results) {
  const total = data.items;
  const noBrand = data.itemsWithoutBrand;

  const lines: string[] = [];
  lines.push(
    `| Configuration | Emitted parseable JSON | Brand correct | Type correct | **Both** | Invented a brand | Median |`,
  );
  lines.push(`|---|---|---|---|---|---|---|`);
  for (const v of data.variants) {
    const parse = v.rows.filter((r) => r.parseOk).length;
    const brand = v.rows.filter((r) => r.brandOk).length;
    const type = v.rows.filter((r) => r.typeOk).length;
    const both = v.rows.filter((r) => r.brandOk && r.typeOk).length;
    const invented = v.rows.filter((r) => r.inventedBrand).length;
    lines.push(
      `| \`${v.id}\` ${v.label} | ${pct(parse, total)} | ${pct(brand, total)} | ${pct(type, total)} | **${both}/${total}** | ${invented}/${noBrand} | ${(median(v.rows) / 1000).toFixed(1)} s |`,
    );
  }
  lines.push("");
  lines.push(
    `Model \`${data.model}\`, temperature ${data.temperature}, ${total} items, one machine, one afternoon.`,
  );
  return lines.join("\n");
}

function patch(file: string, table: string, start: string, end: string) {
  const path = resolve(ROOT, file);
  if (!existsSync(path)) {
    console.log(`skip ${file} (not found)`);
    return;
  }
  const text = readFileSync(path, "utf8");
  const a = text.indexOf(start);
  const b = text.indexOf(end);
  if (a < 0 || b < 0) {
    console.log(`skip ${file} (no markers)`);
    return;
  }
  const next = `${text.slice(0, a + start.length)}\n${table}\n${text.slice(b)}`;
  writeFileSync(path, next);
  console.log(`patched ${file}`);
}

function main() {
  if (!existsSync(EVIDENCE)) {
    console.error(`no evidence at ${EVIDENCE} — run: pnpm evidence:identify`);
    process.exit(1);
  }
  const data = JSON.parse(readFileSync(EVIDENCE, "utf8")) as Results;
  const table = build(data);

  console.log(table);
  console.log();

  patch("README.md", table, "<!-- EVAL_TABLE_START -->", "<!-- EVAL_TABLE_END -->");
  patch("docs/POST.md", table, "<!-- EVAL_TABLE_START -->", "<!-- EVAL_TABLE_END -->");
}

main();
